"""Synchronize guided notebook explanations and an unsolved learner workspace."""
import json
import re
import nbformat as n


def pair(title, text, code, anchor):
    md=n.v4.new_markdown_cell('## '+title+'\n\n'+text);md.id=anchor;md.metadata['id']=anchor
    cell=n.v4.new_code_cell(code);cell.id=anchor+'-code';cell.metadata['id']=cell.id
    return [md,cell]


def enrich(module, pin, setup):
    paths=json.loads((module/'learning-path.json').read_text())
    for notebook in sorted((module/'notebooks').glob('0[1-4]-*.ipynb')):
        nb=n.read(notebook,as_version=4)
        matching=[x for x in paths if x['notebook']==notebook.name]
        links='\n'.join('- ['+x['title']+'](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/'+x['public_path']+')' for x in matching)
        nb.cells[0].source+='\n\nRead the full Campus explanations and activities alongside the code:\n\n'+links+'\n\nFor independent work, use the separate learner workspace. This notebook deliberately shows the reference solution. Pause at each prediction prompt before running its following cell.'
        nb.cells[1].metadata['tags']=['setup'];nb.cells[1].id='setup';nb.cells[1].metadata['id']='setup'
        if notebook.name.startswith('01'):
            nb.cells[2].id='stage-map';nb.cells[2].metadata['id']='stage-map'
            nb.cells[2].source+='\n\nMap the returned DataFrame to ingestion, feature extraction, fitting and evaluation. `partition` selects rows; it never becomes a feature. Predict whether selecting features across all rows fits any statistics, then inspect `preprocess` in the linked source.'
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Trace preparation' in c.source)
            nb.cells[index].id='raw-to-features';nb.cells[index].metadata['id']='raw-to-features'
            nb.cells[index].source+='\n\n`features.loc[train_rows]` selects fitting inputs, and the matching target uses the same mask. The scaler learns only from those fitting rows. `evaluate` calls `predict` on held-out features; it does not fit again. Read the masks before treating the metric as a validation result.'
            nb.cells[index+2:index+2]=pair('Inspect fitted state and row roles','Predict the three printed observations before running: fitting/validation counts, named fitted steps, and number of input features. Distinguish a configured alpha from statistics learned by fitting.',"print(int(train_rows.sum()), int(valid_rows.sum()))\nprint(list(model.named_steps))\nprint(model.named_steps['scale'].n_features_in_)\nassert not (train_rows & valid_rows).any()\nassert features.index.equals(frame.index)",'fitted-state')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Complete the inference' in c.source)
            nb.cells[index].id='batch-proof';nb.cells[index].metadata['id']='batch-proof'
            nb.cells[index].source+='\n\nRegistration/selection here are prepared infrastructure so you can trace the fifth stage. Later lifecycle work explains those decisions. The input has no known target, so this job cannot establish prediction error for tomorrow.'
            nb.cells+=pair('Check the delivered rows','Compare identifiers and finite outputs, then connect the returned source run to the logged execution. A matching row count alone could hide incorrect alignment.',"from campus_mlops.pipeline import DATA\nimport numpy as np\nplanned=pd.read_csv(DATA/'batch-v1.csv')\nassert planned.row_id.tolist()==predictions.row_id.tolist()\nassert np.isfinite(predictions.prediction_kwh).all()\nassert evidence['run_id']==record['run_id']\nprint('Aligned rows:',len(predictions),'complete within deadline:',evidence['complete_within_60s'])",'delivered-rows')
        elif notebook.name.startswith('02'):
            nb.cells[2:2]=pair('Calculate the metric distinction','Illustrative errors A=[2,2,8] and B=[4,4,4] have the same average absolute error. Predict which has larger RMSE and why before calculating. These are teaching values, not experimental scores.',"import numpy as np\nfor label, errors in [('A',[2,2,8]),('B',[4,4,4])]:\n    errors=np.asarray(errors,dtype=float)\n    print(label,'MAE',np.abs(errors).mean(),'RMSE',np.sqrt((errors**2).mean()))",'metric-reasoning')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Run the declared matrix' in c.source)
            nb.cells[index].id='tracking-records';nb.cells[index].metadata['id']='tracking-records'
            nb.cells[index].source+='\n\nThe public `run_matrix` fixture supplies five alpha values; your independent matrix may choose another declared set. Keep the returned IDs: the store can contain other successful executions. Parameters and metrics are not the fitted artifact; the model URI and recovery files carry the next links.'
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Validate an assistant' in c.source)
            nb.cells[index:index]=pair('Compare logging with the model fixed','These two additional runs investigate logging, not model selection. Both use alpha=1, guard=True and the same validation rows. Predict whether validation RMSE should change. Compare actual key sets rather than relying on the config flag.',"off=ws.run(Config(alpha=1,range_guard=True,autolog=False),name='logging-off')\non=ws.run(Config(alpha=1,range_guard=True,autolog=True),name='logging-on')\noff_raw=ws.client.get_run(off['run_id']).data\non_raw=ws.client.get_run(on['run_id']).data\nprint('Added parameters:',sorted(set(on_raw.params)-set(off_raw.params)))\nprint('Added metrics:',sorted(set(on_raw.metrics)-set(off_raw.metrics)))\nassert 'ridge__alpha' in on_raw.params\nassert abs(off['metrics']['rmse_kwh']-on['metrics']['rmse_kwh'])<=1e-6\nassert len(rows)==5",'logging-comparison')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Validate an assistant' in c.source)
            nb.cells[index].id='assistant-review';nb.cells[index].metadata['id']='assistant-review'
            nb.cells[index].source+='\n\nSplit each actual response into claims: winner/metric, controls and operational recommendations. Check every claim against a source field or name the missing evidence. The code below checks numeric selection only; it does not establish that you directed an assistant or reviewed its prose.'
            nb.cells+=pair('Recover the record behind the recommendation','Inspect a stored manifest and compare it with the raw run. This connects the selected table row to recoverable configuration and model identity.',"recovery=Path(ws.client.download_artifacts(best.run_id,'reproduction/manifest.json'))\nsaved=json.loads(recovery.read_text())\nassert saved['run_id']==best.run_id\nassert saved['metrics']['rmse_kwh']==float(best.rmse_kwh)\nprint(saved['config'],saved['model_uri'])",'manifest-check')
        elif notebook.name.startswith('03'):
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Register and approve' in c.source)
            nb.cells[index:index+2]=pair('Register a pending artifact','A run, logged model and registered version are different identities. Record each returned value. Registration must not silently become approval or active selection.',"ws=Workspace(state/'tracking')\napproved=ws.run(Config(alpha=1,range_guard=True),name='baseline-candidate')\nv1=register(ws,approved['run_id'])\ncandidate=ws.client.get_model_version(MODEL_NAME,v1)\nprint(approved['run_id'],approved['model_uri'],v1,candidate.tags)\nassert candidate.tags['validation_status']=='pending'\nassert candidate.run_id==approved['run_id']",'register-pending')+pair('Observe the pending boundary','Predict what happens if a pending version is selected. The helper applies a teaching policy; storing tags and aliases alone would not enforce this decision.',"try:\n    activate(ws,v1,'Deliberate pending-selection probe')\nexcept ValueError as error:\n    print('Expected rejection:',error)\nelse:\n    raise AssertionError('Pending selection accepted')",'registry-identities')+pair('Validate the observed behavior and select','Check a valid table is preserved and an invalid hour rejects. The approval helper also checks finite held-out RMSE and guard configuration; it does not execute your tests for you. Keep the observed rationale distinct from a magic approval label.',"import pandas as pd\nframe=ingest();pd.testing.assert_frame_equal(validate_ranges(frame),frame)\nbad=frame.copy();bad.loc[0,'hour']=24\ntry:\n    validate_ranges(bad)\nexcept ValueError:\n    print('Observed hour=24 rejection')\nelse:\n    raise AssertionError('Invalid hour accepted')\napprove(ws,v1,'Observed valid-copy/hour24 probes and finite validation RMSE<=5')\nprint(activate(ws,v1,'Validated baseline selected'))",'approve-select')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Reproduce the approved' in c.source)
            nb.cells[index].id='reproduce-reference';nb.cells[index].metadata['id']='reproduce-reference'
            nb.cells[index].source+='\n\nThe destination does not exist before this call. The original manifest identifies the recipe. `reproduce` checks current source/data/environment before fitting, then compares the same evaluation partition. New execution IDs are expected; a different snapshot is not. This reference is a new-store replay, not a new-environment proof.'
            nb.cells+=pair('Inspect the source bundle before recovery','A hash cannot reconstruct missing bytes. Inspect the archive members and identify the actual source, data and lock needed for a fresh environment. Do not extract over your working project.',"import tarfile\nsource=Path(ws.client.download_artifacts(approved['run_id'],'reproduction/source.tar.gz'))\nwith tarfile.open(source) as archive:\n    members=archive.getnames()\nprint([name for name in members if name in ['pyproject.toml','uv.lock','src/campus_mlops/pipeline.py','src/campus_mlops/data/demand-v1.csv']])\nassert all(name in members for name in ['pyproject.toml','uv.lock','src/campus_mlops/pipeline.py'])",'source-recovery')
        else:
            nb.cells[2].id='connected-handoff';nb.cells[2].metadata['id']='connected-handoff'
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Reproduce before' in c.source)
            nb.cells[index:index]=pair('Inspect one connected identity chain','Predict which identities should agree before reading them. The registered artifact must point to the selected training run, and the new batch must report that source run and version.',"selected=ws.client.get_model_version_by_alias(MODEL_NAME,'active')\nassert selected.run_id==record['run_id']==inference['run_id']\nassert str(selected.version)==str(version)==inference['resolved_version']\nprint('Run → version → batch:',record['run_id'],version,inference['resolved_version'])",'identity-chain')+pair('Keep a failed candidate from changing active','This is an intentionally rejected candidate, not another configuration to promote. Record active before/after; registration can succeed even when approval fails.',"before=str(ws.client.get_model_version_by_alias(MODEL_NAME,'active').version)\nrejected=ws.run(Config(alpha=100,range_guard=True),name='rejected-candidate')\nrejected_version=register(ws,rejected['run_id'])\ntry:\n    approve(ws,rejected_version,'Deliberate failing gate probe')\nexcept ValueError as error:\n    print('Expected rejection:',error)\nelse:\n    raise AssertionError('Invalid approval accepted')\nafter=str(ws.client.get_model_version_by_alias(MODEL_NAME,'active').version)\nassert before==after",'failed-gate')
            index=next(i for i,c in enumerate(nb.cells) if c.cell_type=='markdown' and 'Evaluate the reserved' in c.source)
            nb.cells[index].source+='\n\nConfiguration selection is already complete in this reference. Report this result separately; do not retune alpha against it or insert it into the validation comparison. The approval policy is validation-based, so final-partition observations cannot be promoted through that gate.'
            nb.cells+=pair('Inspect what the receiver must recover','The notebook replay above used the same environment. A stronger handoff restores the source archive to a new folder, creates a new locked environment and uses a new state. The following inspects real recovery content; follow the full Campus handoff activity for the independent receiving run.',"source=Path(ws.client.download_artifacts(record['run_id'],'reproduction/source.tar.gz'))\nprint('Recoverable source bytes:',source.stat().st_size)\nprint('Recorded command:',record['command'])\nprint('Tolerance:',report['tolerance'],'delta:',report['rmse_delta'])\nassert source.is_file() and report['lineage_matched']",'handoff-recovery')
        for i,c in enumerate(nb.cells):
            if 'id' not in c.metadata:
                slug='cell-'+str(i);c.id=slug;c.metadata['id']=slug
        n.write(nb,notebook)
    # The independent start deliberately contains no run, matrix, registration or rollback solution.
    intro=n.v4.new_markdown_cell('''# Learner workspace — start unsolved

Use this notebook with the [complete Campus learning path](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/lessons/README.md). Make a copy for your investigation. Run setup first, then read the relevant activity below and add your own code/Markdown cells. The setup creates an empty store; it does not perform your experiment, extension or lifecycle decision.

Use Python 3.12. Colab setup clones the pinned GitHub source; locally select the module's locked `.venv` kernel. Save files and artifacts before ending a hosted runtime. See [the execution guide](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/docs/learning-guide.md) for terminal equivalents, edited projects, the local UI and final environment recovery.''');intro.id='learner-start';intro.metadata['id']=intro.id
    setup_cell=n.v4.new_code_cell(setup);setup_cell.id='learner-setup';setup_cell.metadata.update({'id':setup_cell.id,'tags':['setup']})
    support=n.v4.new_code_cell("import os\nif 'google.colab' in sys.modules:\n    subprocess.run([sys.executable,'-m','pip','install','-q','pytest==8.4.2'],check=True)\nPACKAGE=Path(campus_mlops.__file__).resolve().parents[2]\nsys.path.insert(0,str(PACKAGE))\nfrom learning.workspace import make_project, project_python, project_tests, course_cli, prepare_case\nws=Workspace(state/'investigation')\nassert not ws.client.search_runs([ws.experiment_id])\nprint('Empty investigation store:',ws.path)\nprint('Reference source:',PACKAGE)\nprint('Add your decisions and code below; no training or lifecycle action has run.')")
    support.id='workspace-tools';support.metadata['id']=support.id
    nb=n.v4.new_notebook(cells=[intro,setup_cell,support]);nb.metadata={'kernelspec':{'display_name':'Python 3.12','language':'python','name':'python3'},'colab':{'name':'00-learner-workspace.ipynb','provenance':[]}}
    sections={
    'stage-work':('Inspect and edit a bounded stage','Create the intentionally incomplete project with `project = make_project("stage-project")`. Open its printed source path and follow the stage walkthrough. Keep the intended failing test before editing. Use `project_python(project, code)` or `project_tests(project, ...)` to execute changed source in a new process. Do not alter the reference checkout or remove its pin check. The candidate-review activity uses `PACKAGE/exercises/generated-stage-candidate.py`; load it as exercise material, not installed pipeline code.'),
    'experiment-work':('Design and investigate experiments','Write the matrix before executing it. Use the empty `ws` or reopen a deliberately named state. Choose your own declared configurations and retain actual returned IDs. For a prepared unsolved comparison, use `prepare_case("matrix", state/"matrix")`; it logs the fixture but does not compare the runs for you. Autologging practice uses a separate pair so it does not silently expand the model-selection population. The required UI comparison runs in a local clone.'),
    'registry-work':('Inspect a past run or incident','Choose the needed unsolved starting case: `prepare_case("past-run", state/"past")` or `prepare_case("rollback", state/"rollback")`. Read the generated `case.json` and inspect actual tags/source runs. For an edited project, pass `project=project`. Select and execute the target action yourself; the preparation leaves the trial active and performs no rollback. Record before/after observations and new batch/reproduction evidence.'),
    'handoff-work':('Integrate and hand over your own project','Use your actual selected configuration and edited source. Carry returned run/model/version identities through the lifecycle and keep failed-gate evidence. Export the recoverable source/model files while the original store is available. The final fresh-environment proof uses a new local source folder, locked environment and store; a new hosted store alone is not that proof.'),
    'checkpoint-work':('Work independently on the receiving brief','Read the checkpoint in Campus and prepare its supplied inputs without running the solved reference notebook. The registry client uses `prepare_case("registry-assessment", state/"harbor-registry")`; inspect and resolve the incident yourself. Keep the original input/state, your pre-run decisions, exact commands and observed evidence. Instructor solutions are separate from this workspace.')}
    for anchor,(title,text) in sections.items():
        relevant=[x for x in paths if x['notebook_anchor']==anchor]
        links='\n'.join('- ['+x['title']+'](https://github.com/richhiey/ml-llm-ops/blob/main/module-a/'+x['public_path']+')' for x in relevant)
        cell=n.v4.new_markdown_cell('## '+title+'\n\n'+text+'\n\n'+links+'\n\nAdd your investigation cells below this section. Explain what you expect before running and what the observed result establishes afterward. The lesson’s completion criteria and hints guide your self-check.');cell.id=anchor;cell.metadata['id']=anchor;nb.cells.append(cell)
    n.write(nb,module/'notebooks/00-learner-workspace.ipynb')
